/**
 * Detailed roadmap content.
 *
 * The curated roadmaps define the learning path (stage titles + topic names).
 * This module turns that outline into roadmap.sh-style detail:
 *
 *  - every topic gets a one-line explanation plus 3–5 sub-topics (nodes),
 *  - every stage gets a concrete practice project, time estimate, resources
 *    and self-check questions,
 *  - every roadmap gets "what you'll learn" chips and a roadmap.sh link where
 *    an official roadmap exists.
 *
 * Everything is generated locally, so the feature works offline and instantly.
 */

import type {
  Roadmap,
  RoadmapResource,
  RoadmapStage,
  RoadmapTopic,
} from './roadmaps';

export interface DetailedStage {
  title: string;
  description: string;
  project: string;
  hours: string;
  topics: RoadmapTopic[];
  resources: RoadmapResource[];
  checkpoints: string[];
}

export interface RoadmapDetail {
  id: string;
  title: string;
  description: string;
  outcomes: string[];
  totalTopics: number;
  totalSubtopics: number;
  stages: DetailedStage[];
  roadmapUrl?: string;
}

type TopicDetail = { summary: string; subtopics: string[] };

const parseDetail = (text: string): TopicDetail => {
  const [summary, ...subtopics] = text.split('|');
  return { summary, subtopics };
};

const normalize = (value: string): string =>
  value
    .toLowerCase()
    .replace(/&/g, 'and')
    .replace(/[^a-z0-9+#./ ]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

