// ─────────────────────────────────────────────────────────────
// Lookup index
// ─────────────────────────────────────────────────────────────

/**
 * Keys are normalised once at module load, so topics with hyphens, ampersands
 * or prefixes ("K-means", "ADCs / DACs", "GD&T symbols") always resolve.
 * A key may be prefixed with a stage title to disambiguate repeats:
 *   'state and navigation::arguments'
 */
const TOPIC_INDEX = new Map<string, string>();
const STAGE_TOPIC_INDEX = new Map<string, string>();

for (const source of [TOPIC_TEXT, BRANCH_TOPIC_TEXT]) {
  for (const [rawKey, text] of Object.entries(source)) {
    const [stagePart, topicPart] = rawKey.includes('::') ? rawKey.split('::') : ['', rawKey];
    const topicKey = normalize(topicPart);
    if (stagePart) {
      STAGE_TOPIC_INDEX.set(`${normalize(stagePart)}#${topicKey}`, text);
    } else if (!TOPIC_INDEX.has(topicKey)) {
      TOPIC_INDEX.set(topicKey, text);
    }
  }
}

/** Keyword fallback for topics that do not have a dedicated entry. */
const TOPIC_RULES: [RegExp, string][] = [
  [/^$/i, ''],
  [/\b(intro|introduction|basics?|fundamentals?|foundations?|getting started|overview)\b/i, 'Start from the core ideas before adding complexity.|Key definitions|A minimal example|Common misunderstandings|Next steps'],
  [/\b(advanced|expert|mastery)\b/i, 'Go beyond the basics and handle harder cases.|Edge cases|Performance|Best practices|Real-world constraints'],
  [/\b(tools?|tooling|setup|install|installation|workspace|editor|ide)\b/i, 'Set up a workspace that gets out of your way.|Install and configure|Project structure|Useful settings|Shortcuts'],
  [/\b(plan|planning|design|architecture|blueprint)\b/i, 'Decide what to build before you build it.|Requirements|Constraints|Trade-offs|Review'],
  [/\b(test|testing|validation|verification|quality|review)\b/i, 'Check the work against evidence.|Test cases|Expected results|Edge cases|Reporting defects'],
  [/\b(debug|debugging|troubleshoot|diagnos|fix|error)\b/i, 'Isolate the cause instead of guessing.|Reproduce|Narrow the cause|Fix and verify|Prevent recurrence'],
  [/\b(deploy|deployment|release|publish|distribution|ship)\b/i, 'Get the work into the hands of users.|Build artefact|Configuration|Release steps|Rollback plan'],
  [/\b(security|secure|protection|protect|auth|permission|access)\b/i, 'Reduce risk without breaking the workflow.|Threats|Controls|Least privilege|Verification'],
  [/\b(performance|optimis|optimiz|latency|speed|throughput)\b/i, 'Make it fast with measurements, not guesses.|Baseline|Profile|Fix the bottleneck|Re-measure'],
  [/\b(data|dataset|database|storage|persist|memory)\b/i, 'Store and move data without losing it.|Schema|Reads and writes|Consistency|Backup'],
  [/\b(api|endpoint|integration|interface|protocol)\b/i, 'Connect two parts of the system cleanly.|Contract|Request and response|Errors|Versioning'],
  [/\b(ui|ux|screen|layout|visual|chart|dashboard)\b/i, 'Make the result easy to understand and use.|Hierarchy|Layout|States|Accessibility'],
  [/\b(report|reporting|documentation|write|writing|paper|thesis)\b/i, 'Explain the work so someone else can act on it.|Structure|Evidence|Visuals|Recommendation'],
  [/\b(project|portfolio|capstone|case study)\b/i, 'Turn the learning into a finished deliverable.|Scope|Plan|Build|Present'],
  [/\b(standard|codes?|compliance|regulation|specification)\b/i, 'Apply the rules that make the work acceptable.|Which rule applies|Checklist|Evidence|Review'],
  [/\b(safety|hazard|risk|emergency)\b/i, 'Protect people and equipment first.|Identify hazards|Controls|Permits and checks|Emergency response'],
  [/\b(simulat|model|modelling|modeling|digital twin)\b/i, 'Use a simplified model to test decisions.|Assumptions|Inputs|Run and compare|Validate'],
  [/\b(sensor|measure|instrument|calibrat|meter)\b/i, 'Get trustworthy measurements.|Range and accuracy|Wiring|Calibration|Noise'],
  [/\b(control|controller|pid|automation|plc|ladder|scada|hmi)\b/i, 'Keep a process inside its operating limits.|Setpoint|Sensing|Actuation|Tuning and alarms'],
  [/\b(motor|drive|actuator|robot|motion|position)\b/i, 'Move something accurately and safely.|Sizing|Control|Feedback|Safety limits'],
  [/\b(network|communication|ethernet|wireless|mqtt|gateway)\b/i, 'Move data reliably between devices.|Topology|Addressing|Protocol|Diagnostics'],
  [/\b(cloud|server|hosting|aws|azure|gcp|docker|kubernetes)\b/i, 'Run the workload on infrastructure you do not own.|Configuration|Networking|Scaling|Cost'],
  [/\b(ai|ml|machine learning|neural|model training|inference)\b/i, 'Train and evaluate a model honestly.|Data|Baseline|Metrics|Error analysis'],
  [/\b(algorithm|complexity|data structure|optimisation problem)\b/i, 'Solve the problem within the time and space budget.|Model the problem|Choose a pattern|Complexity|Test'],
  [/\b(concept|theory|principle|law|analysis|fundamental)\b/i, 'Understand the principle well enough to apply it.|Definitions|Derivation|Worked example|Limits'],
  [/\b(prototype|practice|exercise|hands-on|lab)\b/i, 'Build the smallest thing that teaches the concept.|Minimal setup|First working version|Iterate|Document'],
];

const resolveFromRules = (topic: string): TopicDetail | null => {
  for (const [pattern, text] of TOPIC_RULES) {
    if (text && pattern.test(topic)) return parseDetail(text);
  }
  return null;
};

const fallbackTopic = (topic: string, stage: RoadmapStage): TopicDetail => ({
  summary: `Understand ${topic.toLowerCase()} and where it fits inside ${stage.title.toLowerCase()}.`,
  subtopics: [
    'Core ideas and vocabulary',
    'A small worked example',
    'Hands-on practice task',
    'Common mistakes to avoid',
  ],
});

function resolveTopic(topic: string, stage: RoadmapStage): TopicDetail {
  const topicKey = normalize(topic);
  const stageKey = `${normalize(stage.title)}#${topicKey}`;
  const text = STAGE_TOPIC_INDEX.get(stageKey) ?? TOPIC_INDEX.get(topicKey);
  if (text) return parseDetail(text);
  return resolveFromRules(topic) ?? fallbackTopic(topic, stage);
}

