const ROADMAP_SH_URLS: Record<string, string> = {
  'web-development': 'https://roadmap.sh/frontend',
  'full-stack': 'https://roadmap.sh/full-stack',
  'backend': 'https://roadmap.sh/backend',
  'android': 'https://roadmap.sh/android',
  'python': 'https://roadmap.sh/python',
  'java': 'https://roadmap.sh/java',
  'cpp': 'https://roadmap.sh/cpp',
  'dsa': 'https://roadmap.sh/datastructures-and-algorithms',
  'sql': 'https://roadmap.sh/sql',
  'cyber-security': 'https://roadmap.sh/cyber-security',
  'cloud-aws': 'https://roadmap.sh/aws',
  'devops': 'https://roadmap.sh/devops',
  'ui-ux': 'https://roadmap.sh/ux-design',
  'blockchain': 'https://roadmap.sh/blockchain',
  'game-dev': 'https://roadmap.sh/game-developer',
  'system-design': 'https://roadmap.sh/system-design',
  'machine-learning': 'https://roadmap.sh/machine-learning',
  'data-science': 'https://roadmap.sh/ai-data-scientist',
};

const HOURS_BY_LEVEL: Record<string, string> = {
  Beginner: '5–7 hrs',
  Intermediate: '7–9 hrs',
  Advanced: '8–10 hrs',
};

const buildOutcomes = (roadmap: Roadmap): string[] => {
  const seen = new Set<string>();
  const outcomes: string[] = [];
  for (const stage of roadmap.stages) {
    const topic = stage.topics[0];
    if (!topic) continue;
    const key = normalize(topic);
    if (seen.has(key)) continue;
    seen.add(key);
    outcomes.push(topic);
    if (outcomes.length >= 8) break;
  }
  return outcomes;
};

const buildCheckpoints = (stage: RoadmapStage): string[] => {
  const [a, b, c] = stage.topics;
  const prompts = [
    a ? `Can you explain ${a.toLowerCase()} without notes?` : `Can you explain the main idea of ${stage.title.toLowerCase()}?`,
    b ? `Can you build a small example that uses ${b.toLowerCase()}?` : `Can you build a small example for this stage?`,
    c ? `Can you spot and fix a common mistake in ${c.toLowerCase()}?` : 'Can you spot and fix a common mistake in this area?',
  ];
  return prompts;
};

/**
 * Stages without hand-picked resources still get a useful study link, so every
 * roadmap (including branch paths) has somewhere to go next.
 */
const buildStageResources = (roadmap: Roadmap, stage: RoadmapStage): RoadmapResource[] => {
  if (stage.resources && stage.resources.length > 0) return stage.resources;
  const focus = stage.topics[0] ?? stage.title;
  const query = encodeURIComponent(`${roadmap.title} ${focus} tutorial`);
  return [
    {
      label: `Watch ${stage.title.toLowerCase()} tutorials`,
      url: `https://www.youtube.com/results?search_query=${query}`,
    },
  ];
};

/**
 * Turn a roadmap outline into full detail. Deterministic and cheap: the
 * result is memoised per roadmap because the data is static.
 */
const detailCache = new Map<string, RoadmapDetail>();

export function getRoadmapDetail(roadmap: Roadmap): RoadmapDetail {
  const cached = detailCache.get(roadmap.id);
  if (cached) return cached;

  const hours = HOURS_BY_LEVEL[roadmap.level] ?? '6–8 hrs';

  const stages: DetailedStage[] = roadmap.stages.map((stage) => {
    const topics = stage.topics.map((topic) => {
      const detail = resolveTopic(topic, stage);
      return { name: topic, ...detail };
    });

    return {
      title: stage.title,
      description: stage.description,
      project:
        STAGE_PROJECTS[normalize(stage.title)] ??
        `Turn this stage into a portfolio piece: ${stage.description.replace(/\.$/, '')}.`,
      hours,
      topics,
      resources: buildStageResources(roadmap, stage),
      checkpoints: buildCheckpoints(stage),
    };
  });

  const detail: RoadmapDetail = {
    id: roadmap.id,
    title: roadmap.title,
    description: roadmap.description,
    outcomes: buildOutcomes(roadmap),
    totalTopics: stages.reduce((sum, stage) => sum + stage.topics.length, 0),
    totalSubtopics: stages.reduce(
      (sum, stage) => sum + stage.topics.reduce((n, topic) => n + topic.subtopics.length, 0),
      0,
    ),
    stages,
    roadmapUrl: ROADMAP_SH_URLS[roadmap.id],
  };

  detailCache.set(roadmap.id, detail);
  return detail;
}
